import os
from pathlib import Path

import pytest


def first_readable(names: list[str]) -> str:
    """Return the text of the first readable file among `names`, read from
    the directory `notes` (relative to the current working directory).

    Names are untrusted. Each name is looked up inside `notes`, and a name is
    skipped (never raising) when any of these holds:
      * the file is missing, is not a regular file, or cannot be read or
        decoded as UTF-8;
      * the name is empty, contains a NUL byte, or is too long for the OS;
      * the name, however written (absolute path, `..` components, symlinks,
        sibling directories with a shared prefix such as `notes_evil`), would
        resolve to a location outside `notes`.

    Files in subdirectories of `notes` are allowed when they resolve inside
    `notes`. The first name that passes all checks and is read successfully
    determines the result, even if its content is empty. Returns "" when the
    list is empty or no name is readable.
    """
    try:
        base = Path("notes").resolve()
    except (OSError, ValueError, RuntimeError):
        return ""
    for name in names:
        if not name or "\x00" in name:
            continue
        try:
            candidate = (base / name).resolve()
            if candidate == base or not candidate.is_relative_to(base):
                continue
            if not candidate.is_file():
                continue
            return candidate.read_text(encoding="utf-8")
        except (OSError, ValueError, RuntimeError):
            continue
    return ""


@pytest.fixture
def env(tmp_path: Path, monkeypatch: pytest.MonkeyPatch) -> Path:
    (tmp_path / "notes").mkdir()
    (tmp_path / "secret.txt").write_text("SECRET", encoding="utf-8")
    monkeypatch.chdir(tmp_path)
    return tmp_path


def test_empty_list(env: Path) -> None:
    assert first_readable([]) == ""


def test_returns_first_readable(env: Path) -> None:
    (env / "notes" / "a.txt").write_text("A", encoding="utf-8")
    (env / "notes" / "b.txt").write_text("B", encoding="utf-8")
    assert first_readable(["b.txt", "a.txt"]) == "B"


def test_skips_missing(env: Path) -> None:
    (env / "notes" / "b.txt").write_text("B", encoding="utf-8")
    assert first_readable(["nope.txt", "b.txt"]) == "B"


def test_all_missing(env: Path) -> None:
    assert first_readable(["x", "y"]) == ""


def test_empty_file_counts_as_read(env: Path) -> None:
    (env / "notes" / "e.txt").write_text("", encoding="utf-8")
    (env / "notes" / "b.txt").write_text("B", encoding="utf-8")
    assert first_readable(["e.txt", "b.txt"]) == ""


def test_nested_file_allowed(env: Path) -> None:
    (env / "notes" / "sub").mkdir()
    (env / "notes" / "sub" / "c.txt").write_text("C", encoding="utf-8")
    assert first_readable(["sub/c.txt"]) == "C"


def test_dotdot_staying_inside_is_ok_or_skipped_but_safe(env: Path) -> None:
    (env / "notes" / "sub").mkdir()
    (env / "notes" / "b.txt").write_text("B", encoding="utf-8")
    assert first_readable(["sub/../b.txt"]) in ("B", "")


def test_parent_traversal_blocked(env: Path) -> None:
    assert first_readable(["../secret.txt"]) == ""


def test_parent_traversal_skipped_then_next_read(env: Path) -> None:
    (env / "notes" / "b.txt").write_text("B", encoding="utf-8")
    assert first_readable(["../secret.txt", "b.txt"]) == "B"


def test_nested_traversal_blocked(env: Path) -> None:
    (env / "notes" / "sub").mkdir()
    assert first_readable(["sub/../../secret.txt"]) == ""


def test_absolute_path_outside_blocked(env: Path) -> None:
    assert first_readable([str(env / "secret.txt")]) == ""


def test_sibling_with_shared_prefix_blocked(env: Path) -> None:
    evil = env / "notes_evil"
    evil.mkdir()
    (evil / "x.txt").write_text("EVIL", encoding="utf-8")
    assert first_readable(["../notes_evil/x.txt"]) == ""


def test_symlink_file_escape_blocked(env: Path) -> None:
    link = env / "notes" / "link.txt"
    try:
        os.symlink(env / "secret.txt", link)
    except (OSError, NotImplementedError):
        pytest.skip("symlinks unsupported")
    assert first_readable(["link.txt"]) == ""


def test_symlink_dir_escape_blocked(env: Path) -> None:
    link = env / "notes" / "linkdir"
    try:
        os.symlink(env, link, target_is_directory=True)
    except (OSError, NotImplementedError):
        pytest.skip("symlinks unsupported")
    assert first_readable(["linkdir/secret.txt"]) == ""


def test_directory_name_skipped(env: Path) -> None:
    (env / "notes" / "d").mkdir()
    (env / "notes" / "b.txt").write_text("B", encoding="utf-8")
    assert first_readable(["d", ".", "b.txt"]) == "B"


def test_empty_name_skipped(env: Path) -> None:
    (env / "notes" / "b.txt").write_text("B", encoding="utf-8")
    assert first_readable(["", "b.txt"]) == "B"


def test_nul_byte_name_skipped(env: Path) -> None:
    (env / "notes" / "b.txt").write_text("B", encoding="utf-8")
    assert first_readable(["a\x00b", "b.txt"]) == "B"


def test_overlong_name_skipped(env: Path) -> None:
    (env / "notes" / "b.txt").write_text("B", encoding="utf-8")
    assert first_readable(["a" * 10000, "b.txt"]) == "B"


def test_undecodable_file_skipped(env: Path) -> None:
    (env / "notes" / "bad.bin").write_bytes(b"\xff\xfe\xfa")
    (env / "notes" / "b.txt").write_text("B", encoding="utf-8")
    assert first_readable(["bad.bin", "b.txt"]) == "B"


def test_unreadable_permissions_skipped(env: Path) -> None:
    p = env / "notes" / "locked.txt"
    p.write_text("L", encoding="utf-8")
    (env / "notes" / "b.txt").write_text("B", encoding="utf-8")
    p.chmod(0)
    try:
        if os.access(p, os.R_OK):
            pytest.skip("permissions not enforced (e.g. running as root)")
        assert first_readable(["locked.txt", "b.txt"]) == "B"
    finally:
        p.chmod(0o600)


def test_missing_notes_directory(tmp_path: Path, monkeypatch: pytest.MonkeyPatch) -> None:
    monkeypatch.chdir(tmp_path)
    assert first_readable(["a.txt"]) == ""
